"""Helper for the three internal cluster systems (uses saved session cookies)."""
import json, sys, urllib.request, http.cookiejar

PORTS = {"rack": 8081, "desk": 8082, "finops": 8083}

def call(system, path, method="GET", body=None):
    port = PORTS[system]
    cj = http.cookiejar.MozillaCookieJar(f"/tmp/capwork/cookies_{port}.txt")
    cj.load(ignore_discard=True, ignore_expires=True)
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj))
    url = f"http://127.0.0.1:{port}{path}"
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(url, data=data, method=method)
    if data:
        req.add_header("Content-Type", "application/json")
    try:
        with opener.open(req) as r:
            raw = r.read().decode()
            try:
                return r.status, json.loads(raw)
            except json.JSONDecodeError:
                return r.status, raw
    except urllib.error.HTTPError as e:
        raw = e.read().decode()
        try:
            return e.code, json.loads(raw)
        except json.JSONDecodeError:
            return e.code, raw

if __name__ == "__main__":
    system, path = sys.argv[1], sys.argv[2]
    method = sys.argv[3] if len(sys.argv) > 3 else "GET"
    body = json.loads(sys.argv[4]) if len(sys.argv) > 4 else None
    status, resp = call(system, path, method, body)
    print("HTTP", status)
    print(json.dumps(resp, ensure_ascii=False, indent=2) if not isinstance(resp, str) else resp)

