#!/usr/bin/env python3
"""Offline search for max-utility rack layout under the discovered physical rules."""
import itertools, json
from collections import defaultdict

RACKS = {
    "R1": {"spine": "A", "zone": "A", "cap": 22.0},
    "R2": {"spine": "A", "zone": "A", "cap": 22.0},
    "R3": {"spine": "A", "zone": "B", "cap": 20.0},
    "R4": {"spine": "B", "zone": "B", "cap": 22.0},
    "R5": {"spine": "B", "zone": "B", "cap": 24.0},
}
TDP = {"T1": 5.5, "T2": 4.2, "T3": 5.5, "T4": 4.2, "T5": 3.0, "T6": 5.5}
HIGH = {"T1", "T3", "T6"}
WEIGHT = {"T1": 30.0, "T2": 22.0, "T3": 20.0, "T4": 12.0, "T5": 10.0, "T6": 6.0}
REQ = {"T1": 4, "T2": 4, "T3": 3, "T4": 4, "T5": 4, "T6": 3}
SHIFT = {"T1": "24H", "T2": "24H", "T3": "24H", "T4": "NIGHT_ONLY", "T5": "DAY_ONLY", "T6": "24H"}
RDMA = {"T1": True}

def windows(shift):
    return ("DAY", "NIGHT") if shift == "24H" else (("DAY",) if shift == "DAY_ONLY" else ("NIGHT",))

# placement = dict team -> tuple of (rack, bay)
def evaluate(pl):
    # power per rack per window
    load = defaultdict(lambda: defaultdict(float))
    occ = defaultdict(dict)  # (rack,bay) -> list of (team, shift)
    for t, bays in pl.items():
        for (r, b) in bays:
            for w in windows(SHIFT[t]):
                load[r][w] += TDP[t]
            occ[(r, b)].append((t, SHIFT[t]))
    for r in RACKS:
        for w in ("DAY", "NIGHT"):
            if load[r][w] > RACKS[r]["cap"] + 1e-9:
                return None
    # overlap: same bay same window two tasks
    for (r, b), items in occ.items():
        ws = defaultdict(list)
        for (t, s) in items:
            for w in windows(s):
                ws[w].append(t)
        for w, ts in ws.items():
            if len(ts) > 1:
                return None
    # T2 zone + no high-IO co-rack same window (T4)
    t2r = {r for (r, b) in pl["T2"]}
    if not t2r <= {"R1", "R2"}:
        return None
    t4r = {r for (r, b) in pl["T4"]}
    if t2r & t4r:
        return None
    # T1 spine-B + rdma racks
    if {r for (r, b) in pl["T1"]} - {"R4", "R5"}:
        return None
    # T3 single spine
    sp = {RACKS[r]["spine"] for (r, b) in pl["T3"]}
    if len(sp) > 1:
        return None
    # thermal bleed: adjacent HIGH bays overlapping window
    bleed = set()
    for r in RACKS:
        for w in ("DAY", "NIGHT"):
            hi = []
            for b in range(4):
