ZONE = {"R1": "A", "R2": "A", "R3": "B", "R4": "B", "R5": "B"}
CAP = {"R1": 22.0, "R2": 22.0, "R3": 20.0, "R4": 22.0, "R5": 24.0}
TDP = {"T1": 5.5, "T2": 4.2, "T3": 5.5, "T4": 4.2, "T5": 3.0, "T6": 5.5}
