WEIGHT = {"T1": 30.0, "T2": 22.0, "T3": 20.0, "T4": 12.0, "T5": 10.0, "T6": 6.0}
REQ = {"T1": 4, "T2": 4, "T3": 3, "T4": 4, "T5": 4, "T6": 3}
SHIFT = {"T1": "24H", "T2": "24H", "T3": "24H", "T4": "NIGHT_ONLY", "T5": "DAY_ONLY", "T6": "24H"}

def wins(s):
    return ("D", "N") if s == "24H" else (("D",) if s == "DAY_ONLY" else ("N",))

# bay options: tuple of (team, shift)
BAY_OPTS = [(), (("T1", "24H"),), (("T2", "24H"),), (("T3", "24H"),), (("T6", "24H"),),
            (("T5", "DAY_ONLY"),), (("T4", "NIGHT_ONLY"),), (("T5", "DAY_ONLY"), ("T4", "NIGHT_ONLY"))]

def rack_configs(rack):
    out = []
    for combo in itertools.product(BAY_OPTS, repeat=4):
        load = {"D": 0.0, "N": 0.0}
        counts = defaultdict(int)
        bleed = set()
        hi = {"D": [], "N": []}
        ok = True
        for b, items in enumerate(combo):
            for (t, s) in items:
                counts[t] += 1
                for w in wins(s):
                    load[w] += TDP[t]
                    if t in HIGH:
                        hi[w].append(b)
        for w in ("D", "N"):
            if load[w] > CAP[rack] + 1e-9:
                ok = False
            for b in hi[w]:
                if b + 1 in hi[w] or b - 1 in hi[w]:
