            continue
        if rem["T2"] > 0 and not ({"R1", "R2"} & set(left)):
            continue
        npl = dict(placement)
        nru = {t: set(v) for t, v in racks_used.items()}
        for b, items in enumerate(combo):
            for (t, s) in items:
                npl.setdefault(t, []).append((r, b))
                nru.setdefault(t, set()).add(r)
        dfs(i + 1, nc, bleed | bl, npl, nru)

