            key = tuple(sorted((t, tuple(sorted(v))) for t, v in placement.items()))
            if key in seen:
                return
            seen.add(key)
            best.append((util, dict(placement), sorted(bleed)))
            return
        r = RACKS[i]
        left = RACKS[i + 1:]
        for combo, cnt, bl in CONFIGS[r]:
            nc = dict(counts)
            over = False
            for t, c in cnt.items():
                nc[t] = nc.get(t, 0) + c
                if nc[t] > REQ[t]:
                    over = True; break
            if over:
                continue
            # remaining supply prune
            ok = True
            for t in REQ:
                rem = REQ[t] - nc.get(t, 0)
                if rem <= 0:
                    continue
                supply = sum(4 for rr in left if t in ALLOW[rr])
                if t == "T1":
                    supply = sum(4 for rr in left if rr in ("R4", "R5"))
                if t == "T2":
                    supply = sum(4 for rr in left if rr in ("R1", "R2"))
                if rem > supply:
                    ok = False; break
            if not ok:
                continue
            npl = dict(placement); nru = {t: set(v) for t, v in racks_used.items()}
            for b, items in enumerate(combo):
                for (t, s) in items:
                    npl.setdefault(t, []).append((r, b)); nru.setdefault(t, set()).add(r)
            dfs(i + 1, nc, bleed | bl, npl, nru)
    dfs(0, {}, frozenset(), {}, {})
    return best, nodes[0], {r: len(CONFIGS[r]) for r in RACKS}

targets = [(), ("T6",), ("T1",), ("T1", "T6"), ("T6", "T3")]
allbest = []
for tg in targets:
    if "T3" in tg:
        continue
    best, nodes, ncfg = search(tg)
    print("target", tg, "configs", ncfg, "nodes", nodes, "feasible", len(best))
    if best:
        best.sort(key=lambda x: -x[0])
        allbest += best
        for util, pl, bl in best[:3]:
            print("  UTIL", round(util, 3), "bleed", bl)
            for t in sorted(pl):
                print("    ", t, sorted(pl[t]))
        break   # first (highest-utility) target that yields solutions wins
allbest.sort(key=lambda x: -x[0])
json.dump([{"util": u, "pl": {t: [list(x) for x in v] for t, v in p.items()}, "bleed": b} for u, p, b in allbest[:30]],
          open("/tmp/capwork/search_results.json", "w"), indent=1)
print("saved", len(allbest))

